// ── API helpers ───────────────────────────────────────────────────────────────
//
// TheAudioDB (free key 123) → artist info, albums, track metadata
// iTunes Search API         → 30-sec MP3 preview URLs (native CORS, no proxy needed)
// TheAudioDB needs a CORS proxy; we try several in order until one works.

const AUDIODB = 'https://www.theaudiodb.com/api/v1/json/123';
const ITUNES  = 'https://itunes.apple.com';

// Proxy list – tried in order, first success wins
const PROXIES = [
  (url) => `https://api.allorigins.win/raw?url=${encodeURIComponent(url)}`,
  (url) => `https://corsproxy.io/?url=${encodeURIComponent(url)}`,
  (url) => `https://api.codetabs.com/v1/proxy?quest=${encodeURIComponent(url)}`,
  (url) => `https://thingproxy.freeboard.io/fetch/${url}`,
];

async function proxiedFetch(path) {
  const target = `${AUDIODB}/${path}`;
  for (const makeProxy of PROXIES) {
    try {
      const res = await fetch(makeProxy(target), { signal: AbortSignal.timeout(6000) });
      if (!res.ok) continue;
      const text = await res.text();
      // Validate it looks like JSON (proxies sometimes return error HTML)
      if (!text.trim().startsWith('{')) continue;
      return JSON.parse(text);
    } catch (_) {
      // try next proxy
    }
  }
  throw new Error('All proxies failed for TheAudioDB');
}

// iTunes has native CORS from browsers — fetch directly, no proxy
async function itunesFetch(params) {
  const url = `${ITUNES}/search?${new URLSearchParams(params)}`;
  const res = await fetch(url, { signal: AbortSignal.timeout(8000) });
  if (!res.ok) throw new Error(`iTunes ${res.status}`);
  return res.json();
}

// ── TheAudioDB endpoints ──────────────────────────────────────────────────────
export const adbSearchArtist = (s) =>
  proxiedFetch(`search.php?s=${encodeURIComponent(s)}`);

export const adbSearchAlbums = (s) =>
  proxiedFetch(`searchalbum.php?s=${encodeURIComponent(s)}`);

export const adbSearchTracks = (s) =>
  proxiedFetch(`searchtrack.php?s=${encodeURIComponent(s)}`);

// ── iTunes endpoints ──────────────────────────────────────────────────────────
export const itunesSearchSongs = (artist, limit = 100) =>
  itunesFetch({ term: artist, entity: 'song', limit });

// Build a lookup map: "artist||track" → previewUrl
export function buildPreviewMap(itunesResults = []) {
  const map = {};
  for (const r of itunesResults) {
    if (r.previewUrl) {
      const key = norm(r.artistName) + '||' + norm(r.trackName);
      map[key] = r.previewUrl;
      // Also index by track name only as a fallback
      if (!map['_track_' + norm(r.trackName)]) {
        map['_track_' + norm(r.trackName)] = r.previewUrl;
      }
    }
  }
  return map;
}

export function lookupPreview(map, artist, track) {
  const key = norm(artist) + '||' + norm(track);
  return map[key] || map['_track_' + norm(track)] || null;
}

function norm(s = '') {
  return s.toLowerCase().replace(/[^a-z0-9]/g, '');
}
